#[ignore = "requires the populated funder regression database"]
async fn loaded_data_grouped_funders_regression() -> anyhow::Result<()> {
    let connection_string = std::env::var("GROUPED_FUNDER_REGRESSION_DATABASE_URL")
        .context("GROUPED_FUNDER_REGRESSION_DATABASE_URL must select the populated database")?;
    let app = start_app(exposed::inbound::http::config::ServerConfig { connection_string }).await?;

    for (term, name, member_count, entry_count, family_key, recorded_name) in [
        ("bbc", "BBC", 12, 71, "bbc", "BBC Studios"),
        ("gb news", "GB News", 7, 77, "gb_news", "GB News Ltd"),
        (
            "premier league",
            "The Premier League",
            8,
            107,
            "premier_league",
            "Premier League International Holdings Ltd",
        ),
    ] {
        let results = search_entities(
            &app,
            &EntitySearchRequest::new_with_strictness(term.into(), 10, 0.8)?,
        )
        .await?;
        assert_eq!(results.len(), 1, "{term}: {results:?}");
        assert_eq!(results[0]["kind"], "Funder");
        assert_eq!(results[0]["name"], name);

        let id = results[0]["id"]
            .as_str()
            .context("search result must include a funder ID")?;
        let details = funder_details(&app, id).await?;
        assert_eq!(details["funder"]["id"], id);
        assert_eq!(
            details["funder"]["member_ids"].as_array().map(Vec::len),
            Some(member_count),
            "{term}"
        );
        assert_eq!(details["entry_count"], entry_count, "{term}");
        assert!(
            details["funder"]["aliases"]
                .as_array()
                .is_some_and(|names| names.iter().any(|name| name == recorded_name)),
            "{term}: missing recorded name {recorded_name}"
        );
        assert!(
            details["funder"]["family_links"]
                .as_array()
                .is_some_and(|links| links.iter().any(|link| link["family_key"] == family_key)),
            "{term}: missing reviewed family evidence"
        );
        assert!(
            details["funder"]["alias_links"]
                .as_array()
                .is_some_and(|links| !links.is_empty()),
            "{term}: missing alias evidence"
        );
    }
    Ok(())
}
#[cfg(test)]
mod tests {
    use super::*;

    fn funder(id: u128, name: &str, aliases: &[&str]) -> GroupingFunder {
        GroupingFunder {
            id: FunderId::new(Uuid::from_u128(id)),
            name: name.into(),
            aliases: aliases.iter().map(|name| (*name).into()).collect(),
        }
    }

    #[test]
    fn connected_components_keep_direct_evidence_and_split_after_bridge_removal() {
        let mut funders = vec![
            funder(3, "Gamma", &["Bridge two", "ALPHA"]),
            funder(1, "Alpha", &["Bridge one"]),
            funder(2, "Beta", &["  BRIDGE\tONE  ", "Bridge two"]),
            funder(4, "Separate", &["  "]),
        ];
        let groups = build_funder_groups(&funders).unwrap();
        assert_eq!(
            groups
                .memberships
                .iter()
                .map(|(id, group)| (id.value().as_u128(), group.value().as_u128()))
                .collect::<Vec<_>>(),
            [(1, 1), (2, 1), (3, 1), (4, 4)]
        );
        assert_eq!(groups.alias_links.len(), 3);
        assert!(groups.family_links.is_empty());
        funders[0].aliases.clear();
        let groups = build_funder_groups(&funders).unwrap();
        assert_eq!(groups.memberships[2].1.value(), Uuid::from_u128(3));
        assert_eq!(groups.alias_links.len(), 1);
    }

    #[test]
    fn reviewed_policy_rejects_ambiguous_names_empty_keys_and_unknown_versions() {
        for input in [
            r#"{"version":2,"families":[]}"#,
            r#"{"version":1,"families":[{"key":"","names":["BBC"]}]}"#,
            r#"{"version":1,"families":[{"key":"a","names":["BBC"]},{"key":"a","names":["Other"]}]}"#,
            r#"{"version":1,"families":[{"key":"a","names":["BBC"]},{"key":"b","names":[" bBc "]}]}"#,
            r#"{"version":1,"families":[{"key":"a","names":[" "]}]}"#,
            r#"{"version":1,"families":[{"key":"a","names":[]}]}"#,
        ] {
            assert!(FamilyPolicy::parse(input).is_err(), "{input}");
        }
        assert!(matches!(
            build_funder_groups(&[funder(1, "Alpha", &[]), funder(1, "Other", &[])]),
            Err(FunderGroupingError::DuplicateFunder(_))
        ));
    }
}

